       "code": "changed = {}\nfor col in [\"name\", \"city\"]:\n    original = raw.loc[clean_df.index, col].astype(str).str.strip()\n    changed[col] = int((original.to_numpy() != clean_df[col].astype(str).to_numpy()).sum())\nprint(changed)\nprint(raw.loc[clean_df.index, [\"name\", \"city\"]].assign(clean_name=clean_df[\"name\"], clean_city=clean_df[\"city\"]).to_string())",
