     "starter": "import numpy as np\nimport pandas as pd\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\nrng = np.random.default_rng(4)\nN = 4000\ntrue = pd.DataFrame({\"customer\": np.arange(N), \"age\": rng.normal(38, 11, N).clip(18, 80).round(), \"spend\": rng.gamma(3, 40, N).round(2), \"visits\": rng.poisson(6, N), \"segment\": rng.choice([\"new\", \"regular\", \"vip\"], N, p=[.4, .5, .1])})\nscore = 0.04 * (true.age - 38) + 0.012 * (true.spend - 120) + 0.25 * true.visits - 0.6 * (true.segment == \"new\") + 1.0 * (true.segment == \"vip\") - 1.2\ntrue[\"repeat\"] = (rng.random(N) < 1 / (1 + np.exp(-score))).astype(int)\nmess = true.copy()\nmess[\"age\"] = mess.age.astype(object)\nmess[\"spend\"] = mess.spend.map(lambda v: f\"Rs {v:,.2f}\").astype(object)\nmess[\"segment\"] = mess.segment.map(lambda s: str(rng.choice([s, s.upper(), \" \" + s + \" \"], p=[.7, .2, .1])))\nbad_age = rng.random(N) < .2\nmess.loc[bad_age, \"age\"] = [str(v) for v in rng.choice([\"\", \"N/A\", \"-1\", \"999\"], int(bad_age.sum()))]\nmess.loc[rng.random(N) < .1, \"visits\"] = -1\nmess = pd.concat([mess, mess.sample(1500, random_state=1)], ignore_index=True)",
