      {
       "name": "df.fillna(df.median(numeric_only=True))",
       "say": "Fill every numeric column with its own median in one line. **Watch for:** `select_dtypes` picks only the numeric columns first.",
       "code": "nums = df.select_dtypes(\"number\")\nfilled = nums.fillna(nums.median())\nprint(filled.isna().sum().sum())"
      }
